public class ClasspathAssemblerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("simple join", "build:libs/a.jar",
                ClasspathAssembler.buildClasspath(java.util.Arrays.asList("build ", "libs/a.jar", "", "build"), ":"));
        check("windows separator", "out;lib/junit.jar",
                ClasspathAssembler.buildClasspath(java.util.Arrays.asList("out", "lib/junit.jar"), ";"));
        check("nulls skipped and trimmed", "a:b",
                ClasspathAssembler.buildClasspath(java.util.Arrays.asList("a", null, " b "), ":"));
        check("everything blank", "",
                ClasspathAssembler.buildClasspath(java.util.Arrays.asList(" ", "", null), ":"));
        check("duplicate after trim", "classes:res",
                ClasspathAssembler.buildClasspath(java.util.Arrays.asList("classes", " classes ", "res"), ":"));
        check("count three", 3, ClasspathAssembler.entryCount("a:b:c", ":"));
        check("count one", 1, ClasspathAssembler.entryCount("build", ":"));
        check("count empty", 0, ClasspathAssembler.entryCount("", ":"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

