public class ClasspathAssembler {

    public static String buildClasspath(java.util.List<String> entries, String separator) {
        java.util.List<String> kept = new java.util.ArrayList<>();
        if (entries != null) {
            for (String entry : entries) {
                if (entry == null) {
                    continue;
                }
                String trimmed = entry.trim();
                if (trimmed.isEmpty() || kept.contains(trimmed)) {
                    continue;
                }
                kept.add(trimmed);
            }
        }
        return String.join(separator, kept);
    }

    public static int entryCount(String classpath, String separator) {
        if (classpath == null || classpath.isEmpty()) {
            return 0;
        }
        int count = 1;
        int index = classpath.indexOf(separator);
        while (index >= 0) {
            count++;
            index = classpath.indexOf(separator, index + separator.length());
        }
        return count;
    }
}
